#ifndef CONFIG_H
#define CONFIG_H

#include <string>
#include <string_view>
#include <unordered_map>
#include <memory>
#include <functional>
#include <initializer_list>

namespace ws {
namespace cfg {

template <typename T, typename... Args>
class Singleton {
public:
    static T& Instance() {
        static T ins(Args...);
        return ins;
    }
private:
    Singleton() = delete;
};

template <typename T, typename... Args>
class SingletonPtr {
public:
    static std::shared_ptr<T> Instance() {
        static std::shared_ptr<T> ins = std::make_shared<T>(Args...);
        return ins;
    }
private:
    SingletonPtr() = delete;
};

template <typename T, typename Cleaner>
class RAII {
public:
    RAII(std::function<void()> cleaner) : cleaner_(cleaner) {}
    ~RAII() { cleaner_(); }
private:
    std::function<void()> cleaner_; 
};

class VarBase {
public:
    virtual ~VarBase() = default;
    virtual std::string_view Name() const = 0;
    virtual std::string_view Description() const = 0;
    virtual std::string ToString() = 0;
    virtual void FromString(std::string_view str) = 0;

    using Ptr = std::shared_ptr<VarBase>;
};

template <typename T>
class Var : public VarBase {
public:
    Var(std::string name, std::string description, const T& val) : name_(std::move(name)), description_(std::move(description)), val_(val) {}

    std::string_view Name() const override {
        return name_;
    }

    std::string_view Description() const override {
        return description_;
    }

    std::string ToString() override {
        return std::to_string(val_);
    }

    void FromString(std::string_view str) override {
        val_ = std::stod(str);
    }

    T GetValue() const {
        return val_;
    }

    void SetValue(const T& val) {
        val_ = val;
    }

private:
    std::string name_; 
    std::string description_; 
    T val_; 
};

class Config {
public:
    Config(std::string name) : name_(std::move(name)) {}

    template <typename T>
    typename Var<T>::Ptr Lookup(const std::string_view name, const T& default_val, const std::string_view description = "") {
        auto it = vars_.find(name);
        if (it != vars_.end()) {
            return std::dynamic_pointer_cast<Var<T>>(it->second);
        } else {
            auto var = std::make_shared<Var<T>>(std::string(name), std::string(description), default_val);
            vars_[name] = var;
            return var;
        }
    }

    template <typename T>
    typename Var<T>::Ptr Lookup(const std::string_view name) const {
        auto it = vars_.find(name);
        if (it != vars_.end()) {
            return std::dynamic_pointer_cast<Var<T>>(it->second);
        } else {
            return nullptr;
        }
    }

    VarBase::Ptr LookupBase(std::string_view name) const {
        auto it = vars_.find(name);
        if (it != vars_.end()) {
            return it->second;
        } else {
            return nullptr;
        }
    }

    std::string_view Name() const {
        return name_;
    }
private:
    std::string name_; 
    std::unordered_map<std::string, VarBase::Ptr> vars_; 
};

}
}

#endif // CONFIG_H

#include "config.h"
#include <iostream>
#include <fstream>
#include <sstream>
#include <yaml-cpp/yaml.h>

namespace ws {
namespace cfg {

Config::Config(std::string name) : name_(std::move(name)) {}

void Config::LoadYamlString(const std::string& str) {
    YAML::Node root = YAML::Load(str);
    if (!root.IsMap()) {
        throw std::invalid_argument("YAML file must contain a map at the root.");
    }

    for (auto const& [key, node] : root) {
        LookupBase(key->as<std::string>());
        if (node.IsScalar()) {
            try {
                auto var = Lookup<double>(key->as<std::string>(), 0.0);
                var->FromString(node.as<std::string>());
            } catch (const std::invalid_argument& e) {
                std::cerr << "Error converting value for key '" << key->as<std::string>() << "': " << e.what() << std::endl;
            }
        }
    }
}

}
}
